function prepareReport(update){
 if(update.label!==preparation.label){
  preparation.timeline.push({at:new Date().toISOString(),elapsedMs:Math.round(performance.now()-preparation.startedAt),label:update.label});
 }
 Object.assign(preparation,update);
 for(const report of prepareListeners)report({progress:preparation.progress,label:preparation.label});
}
function prepare(report){
 if(prepared){report?.({progress:1,label:'City ready'});return preparePromise;}
 if(typeof report==='function'){prepareListeners.add(report);report({progress:preparation.progress,label:preparation.label});}
 if(preparePromise)return preparePromise;
 preparePromise=(async()=>{
  preparation.runs++;
  Object.assign(preparation,{startedAt:performance.now(),timeline:[],error:null});
  prepareReport({progress:0,label:'City world and collision'});
  await new Promise(r=>setTimeout(r,0));
  if(!ensureScene())throw new Error('City could not initialize its renderer.');
  sim.paused=true;
  E.prepareDefinitions(sim.world);
  prepareReport({progress:.12,label:'City district models'});
  await scene.prepare(sim,update=>prepareReport({progress:.12+update.progress*.78,label:update.label}));
  prepareReport({progress:.90,label:'Checking City sound bank'});
  await audio.prepare(update=>prepareReport({progress:.90+.06*update.progress,label:update.label}));
  prepareReport({progress:.97,label:'Rendering the first City frame'});
  await new Promise(r=>setTimeout(r,0));
  scene.render(sim,0);
  prepared=true;
  prepareReport({progress:1,label:'City ready',ready:true});
  return window.PlatdoCity;
 })().catch(error=>{
  preparation.error=preparation.label+' — '+error.message;
  preparation.timeline.push({at:new Date().toISOString(),label:preparation.label,error:error.message});
  preparePromise=null;throw new Error(preparation.error);
 }).finally(()=>prepareListeners.clear());
 return preparePromise;
}
