function refreshSoundControl(){
 const status=audio.status(),retryable=status.failed.length||status.deferred.length;
 soundButton.hidden=!visible||!audio.active||menuPreview?.external||settings.mute||(!status.needsGesture&&!retryable);
 const text=status.needsGesture?'Tap to enable sound':'Retry sound effects';
 if(soundButton.textContent!==text)soundButton.textContent=text;
 soundButton.title=retryable?'Unavailable sounds: '+[...new Set([...status.failed,...status.deferred])].join(', '):'Enable City audio on this device';
 const details=$('#citySoundDetails');
 if(details?.open)details.querySelector('pre').textContent=JSON.stringify(soundDiagnostics(),null,2);
}
function soundDiagnostics(){
 const s=audio.status();
 return {playback:s.contextState,phase:s.phase,loaded:s.loaded,failed:s.failed,deferred:s.deferred,
  pending:s.pending,attempts:s.attempts,lastError:s.lastError,startup:preparation.timeline,events:s.events};
}
soundButton.onclick=()=>{audio.retryFailed();};
