function toast(text){if(['ending','finaleCredits'].includes(screen)){if(!toastQueue.includes(text))toastQueue.push(text);if(toastQueue.length>8)toastQueue.shift();return;}if(toastTimer>0&&$('#cityToast').textContent!==text){if(!toastQueue.includes(text))toastQueue.push(text);if(toastQueue.length>8)toastQueue.shift();return;}$('#cityToast').textContent=text;$('#cityToast').classList.add('show');toastTimer=4.5;}
