 if(screen==='computer'){panel('Home computer',`<p>Choose a game. Your city is saved at your desk.</p><div class="card-grid">${[['code','Code Platdo'],['swing','Platdo Swing'],['godcore','Platdo God Core'],['jump','Platdo Jump']].map(([id,name])=>btn('computerGame',name,'',`data-value="${id}"`)).join('')}</div>`,btn('resume','Close'));return;}
 if(screen==='multiplayer'){panel('City multiplayer',`<p>Open Friends in the online collection to join a City room.</p>`,btn('title','Back'));return;}
 if(screen==='title'){overlay.innerHTML=`<div class="title-shell"><div class="city-title-actions"><div class="eyebrow">YOUR HOME / SOLO PLAY</div><h1 style="margin-top:45px"><small>PLATDO</small>CITY</h1><div class="title-menu">${btn('continue','Continue story <span>→</span>','primary',!save.load('story')?'disabled':'')}${btn('new','New story <span>01</span>')}${btn('sandbox','Sandbox <span>02</span>')}${btn('multiplayer','Friends & multiplayer <span>↗</span>')}${btn('settings','Settings <span>03</span>')}${btn('graphics','Graphics <span>↗</span>')}${btn('controls','Controls <span>04</span>')}${btn('credits','Credits <span>05</span>')}${window.PlatdoCityExit?btn('exit','Main menu <span>Esc</span>'):btn('fullscreen','Full screen <span>↗</span>')}</div></div><div class="city-title-avatar-name">${esc(accountName(menuPreview?.view.profile||sim?.profile))}</div><div class="title-footer">OLD QUAY · GLASSLINE · PALMSTRAND · NORTHPOINT<br><span class="fine">Build ${C.VERSION} · progress saved on this browser</span></div></div>`;return;}
 if(screen==='character'){const cards=P.presets.map((p,i)=>`<button class="card ${preset===i?'selected':''}" data-action="preset" data-value="${i}"><h3>${esc(p.name||['Avery Vale','Quinn Mercer','Jules Vega','Remy Stone','Sasha Reid','Morgan Cross'][i])}</h3><span class="fine">${['Streetwear / balanced silhouette','Tailored layers / close crop','Athletic layers / swept hair','Utility jacket / textured hair','Long coat / side part','Casual layers / tied hair'][i]}</span></button>`).join('');overlay.innerHTML=`<div class="shade" style="background:linear-gradient(90deg,transparent,#071f2977);backdrop-filter:none"><div class="panel character"><div class="panel-header"><div><div class="eyebrow">${mode==='sandbox'?'Separate sandbox save':'A new arrival'}</div><h2>Make yourself at home.</h2></div>${btn('title','Back','ghost')}</div><p class="muted">Playing as <strong id="cityName">${esc(accountName())}</strong></p><div class="card-grid">${cards}</div><p class="fine">All six characters share the same movement and abilities. ${save.load(mode)?'Starting replaces this mode’s current save. Your other profile is preserved.':''}</p>${btn('begin',mode==='sandbox'?'Enter sandbox':'Begin your story','primary')}</div></div>`;return;}
 if(screen==='pause'||screen==='ready'){panel(screen==='ready'?'Ready to resume':'City paused',`<p class="muted">${esc(sim.profile.displayName)} · ${sim.profile.mode==='sandbox'?'Sandbox':'Story / Free roam'} · ${esc(sim.world.districtAt(sim.player.x,sim.player.z)?.name||'Platdo Bay')}</p><div class="stack">${btn('resume',screen==='ready'?'Resume saved game':'Resume','primary')}${btn('returnCity','Return to City')}${btn('openGarage','Garage')}${btn('multiplayer','Friends & multiplayer')}${btn('phone','Phone · missions & activities')}${btn('map','City map')}${btn('weapons','Inventory & equipment')}${btn('save','Save now')}${btn('load','Load saved game','',!save.load(mode)?'disabled':'')}${btn('settings','Settings')}${btn('graphics','Graphics')}${btn('controls','Controls')}${sim.profile.mode==='sandbox'?btn('sandboxTools','Sandbox tools')+btn('newSandbox','New Sandbox','danger','title="Restart sandbox progress; keep your settings"'):''}${sim.mission?btn('retry','Retry checkpoint')+btn('abandon','Abandon current mission','danger'):''}${btn('quit','Save & return to title')}${btn('quitWithoutSave','Quit without saving','danger')}<p class="fine">Quit without saving discards progress since the last save.</p></div>`,save.warning?`<p>${esc(save.warning)}</p>`:'',true);return;}
 if(screen==='newConfirm'){const current=save.load(mode);panel('Replace this profile?',`<p>Begin a new ${mode==='sandbox'?'sandbox':'story'} as <strong>${esc(pendingNewName)}</strong>?</p><p>This replaces <strong>${esc(current?.displayName||'your current profile')}</strong> and its progress. Your other City profile and other Platdo games are preserved.</p><div class="row">${btn('cancelNew','Keep current profile')}${btn('confirmNew','Replace and begin','danger')}</div>`,'',true);return;}
